INSERT INTO "page_content" ("page", "section", "title", "text", "mediaId") VALUES ('about', 'history', 'About Vision Ai', 'Our journey began with a simple observation: the mining, construction, and heavy industries are rich with data, but poor in actionable insights. We bridge that gap. Our team of expert engineers, data scientists, and industry veterans develops ''Smart Simple Solutions'' that integrate seamlessly into existing operations', 20) ON CONFLICT DO NOTHING;
INSERT INTO "page_content" ("page", "section", "title", "text", "mediaId") VALUES ('homepage', 'technology', 'Discover Our Technology', 'Our journey began with a simple observation: the mining, construction, and heavy industries are rich with data, but poor in actionable insights. We bridge that gap. Our team of expert engineers, data scientists, and industry veterans develops ''Smart Simple Solutions'' that integrate seamlessly into existing operations.', 22) ON CONFLICT DO NOTHING;
INSERT INTO "page_content" ("page", "section", "title", "text", "mediaId") VALUES ('homepage', 'hero', 'Simple, Smart AI Solution', 'We provide AI-powered solutions for the mining, construction, and heavy industries, turning your operational data into measurable gains in profitability and sustainability.', 17) ON CONFLICT DO NOTHING;
