INSERT INTO "solution" ("id", "slug", "solutionName", "mediaId", "shortDescription", "longDescription", "ctaText", "ctaLink") VALUES (1, 'fleet-monitoring', 'Production & Fleet Monitoring', 16, 'An all-in-one solution to manage your heavy assets. We use telematics and AI to reduce downtime, cut fuel costs, and optimize your fleet''s performance.', '[{"type":"paragraph","children":[{"text":"Our Fleet Monitoring system provides a real-time, comprehensive view of your entire operation. By integrating with existing telematics data from your heavy machinery, we unlock powerful insights that drive efficiency and reduce operational costs. Our AI models predict maintenance needs before they become critical failures, optimize fuel consumption through intelligent routing and idle-time analysis, and ensure assets are utilized to their maximum potential."}]}]', '', '') ON CONFLICT DO NOTHING;
INSERT INTO "solution" ("id", "slug", "solutionName", "mediaId", "shortDescription", "longDescription", "ctaText", "ctaLink") VALUES (2, 'tailored-ai-solutions', 'Tailored AI Solutions', 24, 'Every operation is unique. Our team can partner with you to build a custom AI engine that solves your most specific and challenging problems.', '[{"type":"paragraph","children":[{"text":"While our standard modules solve common industry challenges, we recognize that no two operations are identical. Our team of expert data scientists and industry veterans can work with you to develop a bespoke AI solution. Whether it''s optimizing a specific metallurgical process, automating quality control inspections, or developing a unique safety protocol, we build custom models that are finely tuned to your specific data and operational goals."}]}]', '', '') ON CONFLICT DO NOTHING;
INSERT INTO "solution" ("id", "slug", "solutionName", "mediaId", "shortDescription", "longDescription", "ctaText", "ctaLink") VALUES (3, 'geotechnical-intelligence', 'GeoTechnical Intelligence', 21, 'Enhance site safety and stability with our AI-driven geotechnical monitoring module. Proactively manage risk and integrate data with your existing platforms.', '[{"type":"paragraph","children":[{"text":"Safety is paramount. The GeoTechnical Intelligence module uses a combination of sensor data, satellite imagery, and computer vision to monitor ground stability, slope angles, and potential hazards in real-time. Our predictive alerts give you early warnings of potential risks, allowing for proactive measures to protect both your personnel and your assets. The system integrates seamlessly with your existing safety protocols and reporting platforms."}]}]', '', '') ON CONFLICT DO NOTHING;
INSERT INTO "solution" ("id", "slug", "solutionName", "mediaId", "shortDescription", "longDescription", "ctaText", "ctaLink") VALUES (4, 'fuel-management-solutions', 'Fuel Management Solutions', 19, 'Our intelligent fuel managements solutions', '{"time":1761633942766,"blocks":[{"id":"XpVXOVTadC","data":{"text":"Turn Every Litre Into Profit","level":3},"type":"header"},{"id":"SPBSm1LTk-","data":{"text":"Fuel is one of the biggest costs in mining, logistics, and construction — and one of the easiest to lose control of. Vision AI’s Fuel Management Solution gives you the power to take full command of your fuel operations, cut wastage, and increase profitability through real-time visibility, automation, and AI-driven insights."},"type":"paragraph"},{"id":"mgVmBhxbNz","data":{"text":"✅ Real-Time Fuel Tracking","level":3},"type":"header"},{"id":"J1sh1gkoY1","data":{"text":"Monitor every liter dispensed, transferred, or consumed across your entire fleet.\nOur IoT-enabled sensors and smart analytics track fuel usage in real time, ensuring accurate measurement, eliminating pilferage, and identifying inefficiencies the moment they occur."},"type":"paragraph"},{"id":"TTnDrhl22j","data":{"text":"📊 Actionable Insights on One Dashboard","level":3},"type":"header"},{"id":"2BGIggVOcl","data":{"text":"Gain complete visibility with a centralized, cloud-based dashboard that displays:"},"type":"paragraph"},{"id":"R8z5I5onKA","data":{"meta":{},"items":[{"meta":{},"items":[],"content":"Live fuel levels and consumption trends\n"},{"meta":{},"items":[],"content":"Refueling and drainage events with GPS and timestamps\n"},{"meta":{},"items":[],"content":"Cost per kilometre, hour, or route\n"},{"meta":{},"items":[],"content":"Driver and operator behaviour analysis\n"}],"style":"unordered"},"type":"list"},{"id":"z3paY9KLj_","data":{"text":"With instant alerts and automated reports, you can take data-driven action anytime, anywhere."},"type":"paragraph"},{"id":"zlEdn8MOFM","data":{"text":"💡 Cut Costs. Boost Margins.","level":3},"type":"header"},{"id":"OioCjhIfLI","data":{"text":"Fuel can account for up to 60% of operational costs in high-demand industries.\nVision AI helps you reduce wastage by up to 30%, improve planning accuracy, and bill clients precisely for hired or leased equipment.\nEvery drop becomes accountable — turning operational data into measurable savings."},"type":"paragraph"},{"id":"ec_wwI8M6W","data":{"text":"⚙️ Seamless Integration","level":3},"type":"header"},{"id":"7m_4hq-6Nh","data":{"text":"Our Fuel Management Solution integrates effortlessly with Vision AI’s Fleet Management and LiDAR Systems, providing a unified ecosystem that connects equipment monitoring, fuel analytics, and site intelligence."},"type":"paragraph"},{"id":"68qnGfvnpq","data":{"text":"📈 Designed for Scale","level":3},"type":"header"},{"id":"scbto0irX4","data":{"text":"From small fleets to large multi-site mining operations, the system scales with your needs.\nIt’s fully customizable, robust in harsh field environments, and tailored to match your industry’s specific operational workflows."},"type":"paragraph"},{"id":"VDpURqgvjc","data":{"text":"Your Command Center for Fuel Intelligence","level":2},"type":"header"},{"id":"51aglq-BbY","data":{"text":"Empower your business with total control over:"},"type":"paragraph"},{"id":"mcy_zog41s","data":{"meta":{},"items":[{"meta":{},"items":[],"content":"Fuel supply chain visibility\n"},{"meta":{},"items":[],"content":"Refill accuracy and consumption forecasting\n"},{"meta":{},"items":[],"content":"Unauthorized usage detection\n"},{"meta":{},"items":[],"content":"Cost control and audit-ready reporting\n"}],"style":"unordered"},"type":"list"},{"id":"C0SAG6tsPO","data":{"text":"Vision AI transforms traditional fuel monitoring into a smart, automated, and transparent process that delivers immediate ROI and long-term efficiency."},"type":"paragraph"},{"id":"egRSaHZsVh","data":{"text":"🚀 Start Saving with Vision AI","level":3},"type":"header"},{"id":"fuM5Hn29TR","data":{"text":"Take the guesswork out of fuel management.\nWith Vision AI’s technology, you’ll know exactly where your fuel is going, how it’s being used, and how to optimize it — every day."},"type":"paragraph"}],"version":"2.31.0-rc.7"}', 'Talk to an Expert today!', '') ON CONFLICT DO NOTHING;
INSERT INTO "solution" ("id", "slug", "solutionName", "mediaId", "shortDescription", "longDescription", "ctaText", "ctaLink") VALUES (5, 'lidar-scanning', 'LiDAR Scanning', 11, 'Get 3D rendered scans of your mine, building, site all for your use!', '{"time":1761636210426,"blocks":[{"id":"3cSLp9jQdu","data":{"text":"Capture Reality. Build with Precision. Plan with Confidence.","level":3},"type":"header"},{"id":"pK-ceSkOoC","data":{"text":"At Vision AI, we bring the future of site intelligence to your fingertips through LiDAR (Light Detection and Ranging) scanning — the most advanced way to capture precise 3D data of your environments, indoors or outdoors, above or below ground."},"type":"paragraph"},{"id":"RTp1KwYQkj","data":{"text":"Whether you''re managing a mine, constructing a building, surveying a property, or designing an interior space, our LiDAR technology empowers you to see what others miss, plan with data, and execute with confidence."},"type":"paragraph"},{"id":"pA1dhz2bl8","data":{"text":"🛰️ What Is LiDAR Scanning?","level":2},"type":"header"},{"id":"QXubHQHyJ6","data":{"text":"LiDAR uses laser pulses to measure distances and create high-resolution, three-dimensional maps of your site.\nIt’s fast, accurate, and reliable — capturing millimeter-level detail across terrain, structures, tunnels, and machinery that traditional surveying simply can’t match."},"type":"paragraph"},{"id":"B4jwck7Ppl","data":{"text":"Our cutting-edge LiDAR equipment includes:"},"type":"paragraph"},{"id":"D9DgNo3367","data":{"meta":{},"items":[{"meta":{},"items":[],"content":"Drone-based scanners for aerial mapping and hazardous areas\n"},{"meta":{},"items":[],"content":"Handheld scanners for quick indoor and underground use\n"},{"meta":{},"items":[],"content":"Vehicle-mounted and tripod units for large-scale, high-precision scans.\n"},{"meta":{},"items":[],"content":"LiDAR-equipped smartphones for portable, agile on-site measurements. \n"}],"style":"unordered"},"type":"list"},{"id":"u7Ygh4m1wZ","data":{"text":"🏗️ Industries We Serve","level":2},"type":"header"},{"id":"QIkpeLWJD5","data":{"text":"Construction Companies","level":3},"type":"header"},{"id":"aqOsXkGDUK","data":{"text":"Transform how you plan and track progress.\nOur LiDAR scanning provides:"},"type":"paragraph"},{"id":"p10SRfNVUl","data":{"meta":{},"items":[{"meta":{},"items":[],"content":"Accurate, build-ready 3D models.\n"},{"meta":{},"items":[],"content":"Real-time progress tracking.\n"},{"meta":{},"items":[],"content":"Early detection of deformations or ground shifts.\n"},{"meta":{},"items":[],"content":"Reduced rework and lower labor costs.\n"}],"style":"unordered"},"type":"list"},{"id":"rGXSagjJLS","data":{"text":"<i>Build smarter. Build faster. Build safer</i>."},"type":"paragraph"},{"id":"zplE0lB5_f","data":{"text":"Mining Houses","level":3},"type":"header"},{"id":"r0PFRlTIGF","data":{"text":"From open cast to deep underground operations, Vision AI’s LiDAR helps you mine smarter and safer:"},"type":"paragraph"},{"id":"MLxZU3Dt2C","data":{"meta":{},"items":[{"meta":{},"items":[],"content":"Identify ore-rich zones faster.\n"},{"meta":{},"items":[],"content":"Detect hazardous voids and slopes.\n"},{"meta":{},"items":[],"content":"Map tunnels, shafts, and stopes with sub-centimeter accuracy.\n"},{"meta":{},"items":[],"content":"Create emergency and evacuation maps.\n"},{"meta":{},"items":[],"content":"Monitor stability and pit walls over time. \n"}],"style":"unordered"},"type":"list"},{"id":"OEAhF9Cjsw","data":{"text":"Our solutions are rugged, reliable, and proven in the harshest mining environments."},"type":"paragraph"},{"id":"ykpmRYwkIH","data":{"text":"Quantity Surveyors","level":3},"type":"header"},{"id":"b11YctuMGx","data":{"text":"Quote with confidence using verifiable 3D data.\nLiDAR enables:"},"type":"paragraph"},{"id":"MBhuL1H2BE","data":{"meta":{},"items":[{"meta":{},"items":[],"content":"Volumetric scans for stockpile measurement.\n"},{"meta":{},"items":[],"content":"Accurate cut-and-fill comparisons.\n"},{"meta":{},"items":[],"content":"Audit-ready reports and visuals.\n"},{"meta":{},"items":[],"content":"Dispute-proof documentation.\n"}],"style":"unordered"},"type":"list"},{"id":"a3BeDSQAvI","data":{"text":"Measure twice, capture once — and trust every calculation.&nbsp;"},"type":"paragraph"},{"id":"bev8y2db7v","data":{"text":"Architects &amp; Interior Designers","level":3},"type":"header"},{"id":"gyD-bgfOt9","data":{"text":"Visualize and design with unparalleled accuracy.\nOur handheld and portable LiDAR scanners deliver:"},"type":"paragraph"},{"id":"ISXUgQobXn","data":{"meta":{},"items":[{"meta":{},"items":[],"content":"Fast room scans in minutes.\n"},{"meta":{},"items":[],"content":"Perfectly aligned floorplans and elevations.\n"},{"meta":{},"items":[],"content":"Rich 3D spatial data for rendering and BIM integration.\n"},{"meta":{},"items":[],"content":"Precision mapping for modern renovations and remodels. \n"}],"style":"unordered"},"type":"list"},{"id":"pxWH4XR73F","data":{"text":"<i>See your vision in true 3D before a single wall moves</i>."},"type":"paragraph"},{"id":"MEGIf9nlFP","data":{"text":"Property Developers &amp; Asset Managers","level":3},"type":"header"},{"id":"qRZIfp6EbH","data":{"text":"For developers, valuers, and facility managers, LiDAR offers data-driven insight for:"},"type":"paragraph"},{"id":"5kYrltn1oH","data":{"meta":{},"items":[{"meta":{},"items":[],"content":"As-built verification and compliance.\n"},{"meta":{},"items":[],"content":"Energy-use and space optimization.\n"},{"meta":{},"items":[],"content":"Maintenance and lifecycle monitoring.\n"},{"meta":{},"items":[],"content":"Integration with AI-based asset management tools.\n"}],"style":"unordered"},"type":"list"},{"id":"XVxwPjr9uN","data":{"text":"<i>Optimize your assets through precision and foresight.</i>"},"type":"paragraph"},{"id":"widS4VVtD4","data":{"text":"💡 Why Choose Vision AI’s LiDAR Solution","level":2},"type":"header"},{"id":"1BcP_iaw_I","data":{"text":"✅ Precision You Can Rely On","level":3},"type":"header"},{"id":"eF6YHPhcDw","data":{"text":"Our systems deliver millimeter to sub-centimeter accuracy, ensuring every line, curve, and elevation is captured faithfully."},"type":"paragraph"},{"id":"XOqlL16qm1","data":{"text":"🧠 Smarter Decision-Making","level":3},"type":"header"},{"id":"kCwhmKHjOS","data":{"text":"Access real-time 3D data and analytics to support faster, evidence-based decisions across your projects."},"type":"paragraph"},{"id":"PnPq_b5W9x","data":{"text":"🛡️ Enhanced Safety","level":3},"type":"header"},{"id":"0nPzM7GJnT","data":{"text":"Scan inaccessible or dangerous areas remotely, reducing risk to personnel and minimizing downtime."},"type":"paragraph"},{"id":"pfps6h9iIp","data":{"text":"⏱️ Save Time, Boost Profitability","level":3},"type":"header"},{"id":"MiRHcMMAdv","data":{"text":"Cut traditional survey times by up to 70%, accelerate project timelines, and reduce costly rework."},"type":"paragraph"},{"id":"Ni4sklx4C4","data":{"text":"⚙️ Seamless CAD/BIM Integration","level":3},"type":"header"},{"id":"nq4kbLzwUE","data":{"text":"Export scan data directly into your preferred design, planning, or engineering software."},"type":"paragraph"},{"id":"YkHtWefW0Z","data":{"text":"💰 Affordable &amp; Scalable Solutions","level":3},"type":"header"},{"id":"RiNw50Y0v3","data":{"text":"Tailored packages for SMEs and enterprises—our pricing scales with your operation size, ensuring fast ROI and long-term valueProduct Brochures-LiDAR."},"type":"paragraph"},{"id":"MMeeuyWXy4","data":{"text":"🌍 Applications Across Industries","level":2},"type":"header"},{"id":"xBJkrJgkzH","data":{"meta":{},"items":[{"meta":{},"items":[],"content":"Construction progress tracking and quality control.\n"},{"meta":{},"items":[],"content":"Mining pit analysis and underground mapping.\n"},{"meta":{},"items":[],"content":"Topographic surveys and terrain modeling.\n"},{"meta":{},"items":[],"content":"Infrastructure inspections.\n"},{"meta":{},"items":[],"content":"Environmental monitoring.\n"},{"meta":{},"items":[],"content":"Forensic and insurance assessments.\n"},{"meta":{},"items":[],"content":"Architectural visualization and renovations.\n"}],"style":"unordered"},"type":"list"},{"id":"Jw5ZF4rBPO","data":{"text":"📈 Empower Your Next Project with Vision AI","level":2},"type":"header"},{"id":"Lkq1bl2sev","data":{"text":"At Vision AI, we merge LiDAR technology, AI analytics, and industry expertise to deliver the most advanced scanning services across Southern Africa — from South Africa and Zimbabwe to Namibia, Botswana, and Malawi."},"type":"paragraph"},{"id":"x3M2rERonh","data":{"text":"With Vision AI, you gain:"},"type":"paragraph"},{"id":"Vpe7jVce5M","data":{"meta":{},"items":[{"meta":{},"items":[],"content":"Faster decisions.\n"},{"meta":{},"items":[],"content":"Safer operations.\n"},{"meta":{},"items":[],"content":"Higher accuracy.\n"},{"meta":{},"items":[],"content":"Data you can trust.\n"}],"style":"unordered"},"type":"list"},{"id":"cL0l7wtfy-","data":{"text":"🗺️ Ready to Experience LiDAR in Action?","level":2},"type":"header"},{"id":"5Ns4plMnuy","data":{"text":"Get a live demo of how LiDAR scanning can transform your next project."},"type":"paragraph"}],"version":"2.31.0-rc.7"}', '', '') ON CONFLICT DO NOTHING;
