INSERT INTO "blog_post" ("slug", "title", "authorId", "mediaId", "contentJson", "isPublished", "publishedAt", "createdAt") VALUES ('the-future-of-heavy-industry-is-ai', 'The Future of Heavy Industry is AI', 'ls75rtjgf74t181', NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Artificial intelligence is no longer a futuristic concept; it is a present-day reality transforming the heavy industry landscape. From predictive maintenance to autonomous vehicles, AI is enhancing efficiency, safety, and profitability.","type":"text"}]}]}', TRUE, '2025-08-14T08:56:48.136Z', '2025-08-14T08:56:48.296Z') ON CONFLICT DO NOTHING;
INSERT INTO "blog_post" ("slug", "title", "authorId", "mediaId", "contentJson", "isPublished", "publishedAt", "createdAt") VALUES ('misconception-vs-reality-are-drones-replacing-surveyors', 'Misconception Vs Reality: Are drones Replacing Surveyors', 'ls75rtjgf74t181', NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Many people think that drones are taking over the jobs of surveyors but in reality, drones","type":"text"},{"type":"hardBreak"},{"text":"are not replacing surveyors. They are simply helping them do their jobs better.","type":"text"}]},{"type":"paragraph","content":[{"text":"According to a blog post from Trimble, AI and robotics have advanced far enough that","type":"text"},{"type":"hardBreak"},{"text":"workers across industries share concern over being replaced. Surveyors often ask us if","type":"text"},{"type":"hardBreak"},{"text":"drones will make their jobs unnecessary—but nothing could be further from the truth. In","type":"text"},{"type":"hardBreak"},{"text":"fact, we’re passionate believers that drones are actively improving the professional","type":"text"},{"type":"hardBreak"},{"text":"landscape for surveyors, engineers, contractors, and other earthworks professionals.","type":"text"},{"type":"hardBreak"},{"text":"Various industries are integrating drones into their workflows as drone technology","type":"text"},{"type":"hardBreak"},{"text":"becomes increasingly streamlined and accessible. Drones can dramatically increase","type":"text"},{"type":"hardBreak"},{"text":"productivity and efficiency. As a result, drones are changing the way businesses operate","type":"text"},{"type":"hardBreak"},{"text":"by reducing costs, saving time, improving safety, and ensuring a direct return on","type":"text"},{"type":"hardBreak"},{"text":"investment. The use of drones has revolutionized surveying.","type":"text"}]},{"type":"paragraph","content":[{"text":"In the world of mining, surveying is a critical task that provides the vital data needed to","type":"text"},{"type":"hardBreak"},{"text":"plan, operate, and maintain complex extraction sites. Traditionally, this work has","type":"text"},{"type":"hardBreak"},{"text":"involved teams of surveyors painstakingly traversing rugged terrain, taking","type":"text"},{"type":"hardBreak"},{"text":"measurements and observations by hand. However, a new tool is transforming the","type":"text"},{"type":"hardBreak"},{"text":"surveyor’s role, the drone.","type":"text"}]},{"type":"paragraph","content":[{"text":"Drones are not replacing surveyors, but rather enhancing their capabilities in","type":"text"},{"type":"hardBreak"},{"text":"remarkable ways. They are a valuable tool in a surveyor’s toolbox. Like any other tool,","type":"text"},{"type":"hardBreak"},{"text":"they are only useful in conjunction with people, not instead of them. These unmanned","type":"text"},{"type":"hardBreak"},{"text":"aerial vehicles (UAVs) can quickly and safely gather data from large, inaccessible, and","type":"text"},{"type":"hardBreak"},{"text":"hazardous areas of a mine site. Using high-resolution cameras and other specialized","type":"text"},{"type":"hardBreak"},{"text":"sensors, drones can capture detailed aerial imagery, 3D models, and topographical","type":"text"},{"type":"hardBreak"},{"text":"maps that would be extremely difficult and dangerous for human surveyors to obtain.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Here are some of the ways drones complement the work of surveyors","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Aerial Data Capture: Drones can quickly and safely capture aerial imagery and","type":"text"},{"type":"hardBreak"},{"text":"data that would be difficult or dangerous for surveyors to obtain using traditional","type":"text"},{"type":"hardBreak"},{"text":"methods. This data can then be used by surveyors to create more detailed and","type":"text"},{"type":"hardBreak"},{"text":"accurate maps, models, and measurements.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Detailed 3D Modeling: The high-resolution aerial data collected by drones can be","type":"text"},{"type":"hardBreak"},{"text":"processed into detailed 3D models of the mining site, providing surveyors with a","type":"text"},{"type":"hardBreak"},{"text":"comprehensive digital representation that they can use for various analysis and","type":"text"},{"type":"hardBreak"},{"text":"planning tasks.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Monitoring and Inspection: Drones can be programmed to conduct regular,","type":"text"},{"type":"hardBreak"},{"text":"automated inspections of the mining site, monitoring for changes, potential","type":"text"},{"type":"hardBreak"},{"text":"hazards, and progress over time. Surveyors can then use this data to identify","type":"text"},{"type":"hardBreak"},{"text":"areas that require further investigation or intervention.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Improved Safety: By accessing hazardous or inaccessible areas with drones,","type":"text"},{"type":"hardBreak"},{"text":"mining companies can reduce the risk to their surveying personnel, improving","type":"text"},{"type":"hardBreak"},{"text":"overall safety and compliance with industry regulations.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Increased Productivity: The combination of drone-collected data and surveyor expertise","type":"text"},{"type":"hardBreak"},{"text":"can lead to more efficient and effective decision-making, ultimately increasing the","type":"text"},{"type":"hardBreak"},{"text":"productivity and cost-effectiveness of mining operations.","type":"text"}]},{"type":"paragraph","content":[{"text":"“Drones have become an invaluable asset for mine surveyors,” explains Jane Thompson,","type":"text"},{"type":"hardBreak"},{"text":"a senior mining engineer. “They allow us to work faster, more safely, and with greater","type":"text"},{"type":"hardBreak"},{"text":"accuracy than ever before. The data we can collect from a single drone survey is simply","type":"text"},{"type":"hardBreak"},{"text":"astounding.” Drones make surveyors’ work safer and more enjoyable in the following","type":"text"},{"type":"hardBreak"},{"text":"ways:","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Worksite safety: Drones can fly over hazardous terrain, eliminating the need for","type":"text"},{"type":"hardBreak"},{"text":"surveyors to put themselves at risk.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dispute resolution: A single, shared source of truth keeps everyone on the same","type":"text"},{"type":"hardBreak"},{"text":"page, making disputes a rare occurrence.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Less redundant work: Bad or confusing data creates redundant work, which has","type":"text"},{"type":"hardBreak"},{"text":"a massive downstream impact on your bottom line. This can be prevented with","type":"text"},{"type":"hardBreak"},{"text":"fast, frequent surveys and updates one can share with all stakeholders.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Avoid downtime: Know ahead of time if a site isn’t ready for your crew—and get","type":"text"},{"type":"hardBreak"},{"text":"the pictures to prove it. Our clients save thousands of dollars per day in avoided","type":"text"},{"type":"hardBreak"},{"text":"downtime.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Worker satisfaction: Safer, more efficient worksites create happier employees,","type":"text"},{"type":"hardBreak"},{"text":"reduce turnover, and boost workplace morale.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"For example, from an article By Olivia Lewis on drone surveys a team of surveyors using","type":"text"},{"type":"hardBreak"},{"text":"drones was able to map an entire 100-acre open-pit mine in just a few hours. The","type":"text"},{"type":"hardBreak"},{"text":"detailed 3D model they generated provided crucial insights into the mine’s geography,","type":"text"},{"type":"hardBreak"},{"text":"infrastructure, and excavation progress – information that would have taken weeks to","type":"text"},{"type":"hardBreak"},{"text":"gather manually. Conventionally, it would take surveyors several weeks to carry out","type":"text"},{"type":"hardBreak"},{"text":"such work without using drones.","type":"text"}]},{"type":"paragraph","content":[{"text":"Crucially, drone technology does not diminish the need for human expertise. Surveyors","type":"text"},{"type":"hardBreak"},{"text":"are still essential for interpreting the vast amounts of data collected, identifying trends","type":"text"},{"type":"hardBreak"},{"text":"and anomalies, and making informed decisions that drive mining operations forward.","type":"text"},{"type":"hardBreak"},{"text":"Drones simply empower surveyors to work more efficiently and effectively.","type":"text"}]},{"type":"paragraph","content":[{"text":"Drones are not replacing surveyors but helping them work better. They quickly and","type":"text"},{"type":"hardBreak"},{"text":"safely gather data from large and complex areas, aiding in creating detailed maps and","type":"text"},{"type":"hardBreak"},{"text":"models. Human expertise is still needed for interpreting data, making decisions, and","type":"text"},{"type":"hardBreak"},{"text":"managing projects. Surveyors using drones can work faster and more accurate.","type":"text"}]},{"type":"paragraph","content":[{"text":"As the mining industry continues to evolve, the partnership between surveyors and","type":"text"},{"type":"hardBreak"},{"text":"drones will only grow stronger. By embracing this drone technology, making use of the","type":"text"},{"type":"hardBreak"},{"text":"best surveying drones like the DJI Phantom 4 RTKa and Elios 3, mining companies can","type":"text"},{"type":"hardBreak"},{"text":"optimise their operations, reduce risks, and stay ahead of the curve in an increasingly","type":"text"},{"type":"hardBreak"},{"text":"competitive global market","type":"text"}]}]}', TRUE, NULL, '2025-08-14T09:08:55.009Z') ON CONFLICT DO NOTHING;
